                            if (this->CoolingTowerAFRRFailedCount < 1) {
                                ++this->CoolingTowerAFRRFailedCount;
                                ShowWarningError(
                                    state,
                                    std::format("CoolingTower:VariableSpeed \"{}\" - Cooling tower air flow rate ratio calculation failed ",
