                                ShowContinueError(
                                    state,
                                    std::format("...with conditions as Twb = {:5.2F}, Trange = {:5.2F}, Tapproach = {:5.2F}, and water flow "
                                                "rate ratio = {:5.2F}",
                                                TwbCapped,
                                                Tr,
                                                Ta,
